const fetchMeta = $('Pre-Works Fetch Summary1').first().json || {};
const html = ($('Fetch Pre-Works Table HTML').first().json || {}).html || '';
const ASBESTOS_SUFFIX = '_wi_pw_24818_upload';
const UPRN_SUFFIX = '_property_ref';
const ADDR_SUFFIX = '_address';
const CORF_SUFFIX = '_client_order_reference';

function cellClass(attrs) {
  const m = String(attrs || '').match(/class="([^"]*)"/i);
  if (!m) return '';
  return m[1].split(/\s+/).find(c => c.startsWith('jqgrid_bg_')) || '';
}
function cellTitle(attrs) {
  const m = String(attrs || '').match(/title="([^"]*)"/i);
  return m ? m[1].trim() : '';
}

const trRegex = /<tr[^>]+id="(\d+)"[^>]*>([\s\S]*?)<\/tr>/gi;
const rows = [];
let trMatch;
while ((trMatch = trRegex.exec(html)) !== null) {
  const rowId = trMatch[1];
  const rowHtml = trMatch[2];
  const cells = {};
  const tdRegex = /<td([^>]+)>([\s\S]*?)<\/td>/gi;
  let tdMatch;
  while ((tdMatch = tdRegex.exec(rowHtml)) !== null) {
    const keyMatch = tdMatch[1].match(/aria-describedby="([^"]+)"/i);
    if (!keyMatch) continue;
    cells[keyMatch[1]] = { attrs: tdMatch[1] };
  }
  function getCell(suffix) {
    for (const [key, val] of Object.entries(cells)) {
      if (key.endsWith(suffix)) return val;
    }
    return null;
  }
  const asbCell = getCell(ASBESTOS_SUFFIX);
  if (!asbCell) continue;
  const asbClass = cellClass(asbCell.attrs);
  if (!asbClass.includes('red')) continue;
  rows.push({
    pre_work_id: rowId,
    uprn: cellTitle(getCell(UPRN_SUFFIX)?.attrs),
    address: cellTitle(getCell(ADDR_SUFFIX)?.attrs),
    client_order_reference: cellTitle(getCell(CORF_SUFFIX)?.attrs),
    asbestos_class: asbClass,
  });
}

console.log(`${fetchMeta.verify_message || ''} | Red asbestos rows=${rows.length}`);
if (!rows.length) {
  return [{ json: { _no_red_rows: true, red_count: 0, message: 'No red Global Asbestos Survey rows on pre-works report.' } }];
}
return rows.map(r => ({ json: r }));

function bodyFrom(resp) {
  let body = resp.body ?? resp.data ?? resp;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { body = {}; }
  }
  if (body && body.body && body.items === undefined && body.total === undefined) {
    body = body.body;
  }
  return body || {};
}
function normCorf(v) {
  const raw = String(v ?? '').trim();
  if (!raw) return '';
  const t = raw.toLowerCase().replace(/\s+/g, '');
  const slash = t.match(/^(\d+)\/(\d+)$/);
  if (slash) return parseInt(slash[1], 10) + '/' + parseInt(slash[2], 10);
  const digits = t.replace(/\D/g, '');
  if (digits.length >= 4) return String(parseInt(digits, 10));
  return t;
}
function cleanAddrKey(str) {
  return String(str || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').replace(/\s+/g, ' ').trim();
}
const resp = $input.first().json || {};
const data = bodyFrom(resp);
const items = Array.isArray(data.items) ? data.items : [];
const corfToWorksId = {};
const addrToWorksId = {};
for (const item of items) {
  const wid = String(item.works_id || '').trim();
  if (!wid) continue;
  const corf = normCorf(item.client_order_reference || '');
  if (corf) corfToWorksId[corf] = wid;
  const addr = cleanAddrKey(item.address || '');
  if (addr) addrToWorksId[addr] = wid;
}
const sd = $getWorkflowStaticData('global');
sd.corfToWorksId = corfToWorksId;
sd.addrToWorksId = addrToWorksId;
return [{
  json: {
    works_index_total: data.total ?? items.length,
    works_index_ok: data.success === true,
    corf_map_size: Object.keys(corfToWorksId).length,
    message: data.message || `Indexed ${items.length} works`,
  },
}];

const driveId = $('Get BCC library drive').first().json.id;
const spFiles = ($('List asbestos folder').first().json.value || []).filter(f => f.file && f.name.toLowerCase().endsWith('.pdf'));
const rows = $('Parse Red Asbestos Rows').all().map(i => i.json || {}).filter(r => !r._no_red_rows);
const sd = $getWorkflowStaticData('global');
const corfToWorksId = sd.corfToWorksId || {};
const addrToWorksId = sd.addrToWorksId || {};

function normCorf(v) {
  const raw = String(v ?? '').trim();
  if (!raw) return '';
  const t = raw.toLowerCase().replace(/\s+/g, '');
  const slash = t.match(/^(\d+)\/(\d+)$/);
  if (slash) return parseInt(slash[1], 10) + '/' + parseInt(slash[2], 10);
  const digits = t.replace(/\D/g, '');
  if (digits.length >= 4) return String(parseInt(digits, 10));
  return t;
}
function cleanAddress(str) {
  let c = String(str || '').toLowerCase().replace(/\([^)]*\)/g, ' ');
  c = c.replace(/[^a-z0-9]/g, ' ').replace(/\s+/g, ' ').trim();
  return c;
}
function cleanAddrKey(str) { return cleanAddress(str); }
function cleanFilename(str) {
  let c = String(str || '').toLowerCase();
  c = c.replace(/\.pdf$/, '').replace(/_asbestos(\s*\(\d+\))?$/, '');
  c = c.replace(/[^a-z0-9]/g, ' ').replace(/\s+/g, ' ').trim();
  return c;
}
function similarity(s1, s2) {
  if (!s1 || !s2) return 0;
  if (s1.includes(s2) || s2.includes(s1)) return 1.0;
  const ns1 = s1.replace(/\s/g, '');
  const ns2 = s2.replace(/\s/g, '');
  if (ns1.includes(ns2) || ns2.includes(ns1)) return 1.0;
  const w1 = s1.split(' ');
  const w2 = s2.split(' ');
  if (w1.length >= 2) {
    const p2 = w1.slice(0, 2).join(' ');
    const p3 = w1.length >= 3 ? w1.slice(0, 3).join(' ') : p2;
    if (s2.includes(p3)) return 1.0;
    if (s2.includes(p2)) return 0.95;
  }
  const shortW = w1.length < w2.length ? w1 : w2;
  const longW = new Set(w1.length < w2.length ? w2 : w1);
  let mc = 0;
  for (const w of shortW) { if (longW.has(w)) mc++; }
  return shortW.length > 0 ? mc / shortW.length : 0;
}

const pending = [];
const skipped = [];

for (const row of rows) {
  const corfRaw = String(row.client_order_reference || '').trim();
  const corf = normCorf(corfRaw) || corfRaw;
  const addr = String(row.address || '').trim();
  const cAddr = cleanAddress(addr);
  let fileName = '';
  let bestScore = 0;
  let bestFile = null;
  for (const f of spFiles) {
    const cFile = cleanFilename(f.name);
    const score = similarity(cAddr, cFile);
    if (score > bestScore) { bestScore = score; bestFile = f; }
  }
  if (bestScore >= 0.80 && bestFile) {
    fileName = bestFile.name;
  } else {
    skipped.push({ pre_work_id: row.pre_work_id, corf, address: addr, reason: 'no_sharepoint_match', bestScore });
    continue;
  }
  const works_id = (corf && corfToWorksId[corf]) || (cAddr && addrToWorksId[cleanAddrKey(addr)]) || '';
  if (!works_id) {
    skipped.push({ pre_work_id: row.pre_work_id, corf, address: addr, reason: 'no_works_id', fileName });
    continue;
  }
  pending.push({
    json: {
      _skip: false,
      pre_work_id: row.pre_work_id,
      corf: corfRaw || corf,
      works_id,
      address: addr,
      uprn: row.uprn || '',
      asbestos_report_file: fileName,
      download_url: `https://graph.microsoft.com/v1.0/drives/${driveId}/root:/RR Job imports and JIS/Asbestos reports/${encodeURIComponent(fileName)}:/content`,
    },
  });
}

if (pending.length === 0) {
  return [{ json: { _skip: true, message: 'No pending uploads.', skipped_count: skipped.length, skipped } }];
}
return pending;

function pairedIndex(item, fallback) {
  const p = item?.pairedItem;
  if (Array.isArray(p)) {
    const hit = p.find(x => x && typeof x.item === 'number');
    if (hit) return hit.item;
  } else if (p && typeof p.item === 'number') {
    return p.item;
  }
  return fallback;
}
const filterItems = $('Match SharePoint PDFs').all().filter(i => !i.json?._skip);
const idx = pairedIndex($input.item, $itemIndex);
const row = { ...(filterItems[idx]?.json || $('Match SharePoint PDFs').item.json || {}) };
const corf = String(row.corf || '').trim();
const fileName = String(row.asbestos_report_file || '').trim();
let buffer;
try {
  buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
} catch (e) {
  return { json: { ...row, _encode_error: `No binary for CORF ${corf}: ${e.message}`, _skip: true } };
}
const size = buffer.length;
if (size < 256) {
  return { json: { ...row, _encode_error: `PDF too small (${size} bytes)`, _skip: true } };
}
if (buffer.slice(0, 4).toString() !== '%PDF') {
  return { json: { ...row, _encode_error: `Not a PDF for CORF ${corf}`, _skip: true } };
}
return { json: { ...row, _pdf_base64: buffer.toString('base64'), _pdf_size: size, _skip: false } };

const apiBase = String($('Set API URL').first().json.api_base_url || '').replace(/\/+$/, '');
const rows = $('Encode PDF Base64').all();
const items = [];
const batchMeta = [];
const skipped = [];
for (const item of rows) {
  const j = item.json || {};
  const base = { pre_work_id: j.pre_work_id, corf: j.corf, works_id: j.works_id };
  if (j._skip) {
    skipped.push({ ...base, _status: `ERROR: ${j._encode_error || 'Skipped'}`, _api_success: false });
    continue;
  }
  const corf = String(j.corf || '').trim();
  const wid = String(j.works_id || '').trim();
  const fileName = String(j.asbestos_report_file || '').trim();
  const b64 = String(j._pdf_base64 || '').trim();
  if (!corf || !wid || !fileName || !b64) {
    skipped.push({ ...base, _status: 'ERROR: Missing corf/works_id/file/base64', _api_success: false });
    continue;
  }
  items.push({ corf, works_id: wid, pdf_filename: fileName, pdf_base64: b64 });
  batchMeta.push({ ...base, pdf_filename: fileName });
}
return [{
  json: {
    _api_url: `${apiBase}/upload-asbestos-pdf-batch`,
    _skipped: skipped,
    _batch_meta: batchMeta,
    _batch_body: { items, contract_id: '321129', use_works_id_navigation: true, timeout_ms: 45000 },
    _item_count: items.length,
    _skipped_count: skipped.length,
  },
}];

const agg = $('Aggregate Batch Payload').first().json;
const skipped = agg._skipped || [];
const batchMeta = agg._batch_meta || [];
const pendingByKey = {};
for (const item of $('Match SharePoint PDFs').all()) {
  const j = item.json || {};
  if (j._skip) continue;
  const key = `${j.works_id}::${j.corf}`;
  pendingByKey[key] = j;
}
function resolvePending(meta) {
  const key = `${meta.works_id}::${meta.corf}`;
  return pendingByKey[key] || {};
}
function mapApiResult(r, meta) {
  const pending = resolvePending(meta);
  const msg = String(r.message || '').toLowerCase();
  const already = !!(r.already_uploaded || msg.includes('already present'));
  const ok = !!(r.success || r.uploaded || already);
  const status = ok ? 'true' : `ERROR: ${r.error || r.message || 'Unknown error'}`;
  return {
    pre_work_id: pending.pre_work_id ?? meta.pre_work_id,
    corf: r.corf || meta.corf || pending.corf,
    works_id: r.works_id || meta.works_id || pending.works_id,
    address: pending.address || '',
    uprn: pending.uprn || '',
    asbestos_report_file: meta.pdf_filename || pending.asbestos_report_file || '',
    _status: status,
    _api_success: ok,
    _already_uploaded: already,
    _newly_uploaded: !!r.uploaded,
  };
}
function extractResults(resp) {
  const statusCode = resp.statusCode ?? resp.status ?? 0;
  let body = resp.body ?? resp.data ?? resp;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { body = {}; }
  }
  if (body && typeof body === 'object' && body.body && !body.results) body = body.body;
  const results = Array.isArray(body?.results) ? body.results : [];
  return { statusCode, body: body || {}, results };
}
function markErrors(metaList, errMsg) {
  return metaList.map(meta => {
    const pending = resolvePending(meta);
    return {
      pre_work_id: pending.pre_work_id ?? meta.pre_work_id,
      corf: meta.corf,
      works_id: meta.works_id,
      address: pending.address || '',
      _status: `ERROR: ${errMsg}`,
      _api_success: false,
    };
  });
}
let apiResults = [];
if (agg._item_count > 0) {
  const postItems = $('POST upload-asbestos-pdf-batch').all();
  const resp = postItems.length ? (postItems[0].json || {}) : ($input.first()?.json || {});
  const { results, statusCode, body } = extractResults(resp);
  if (results.length > 0) {
    for (let idx = 0; idx < results.length; idx++) {
      apiResults.push(mapApiResult(results[idx], batchMeta[idx] || {}));
    }
    if (results.length < batchMeta.length) {
      const tail = batchMeta.slice(results.length);
      apiResults.push(...markErrors(tail, `Batch interrupted (HTTP ${statusCode || 'unknown'})`));
    }
  } else if (batchMeta.length > 0) {
    const err = body.detail || body.message || body.error || `HTTP ${statusCode || 'connection failed'}`;
    apiResults.push(...markErrors(batchMeta, err));
  }
}
const all = [...skipped, ...apiResults];
return all.map(j => ({ json: j }));

const rows = $('Expand Batch Results').all().map(i => i.json || {});
let newlyUploaded = 0, alreadyUploaded = 0, errors = 0;
const errorDetails = [];
for (const r of rows) {
  const status = String(r._status ?? '').trim();
  if (status === 'true') {
    if (r._already_uploaded) alreadyUploaded++;
    else newlyUploaded++;
  } else if (status.startsWith('ERROR:')) {
    errors++;
    errorDetails.push({ corf: r.corf, works_id: r.works_id, error: status });
  }
}
return [{
  json: {
    total_results: rows.length,
    newly_uploaded: newlyUploaded,
    already_on_easybop: alreadyUploaded,
    errors,
    error_details: errorDetails,
  },
}];

const raw = $input.first().json || {};
const html = String(raw.html || '');
const ids = [];
const re = /<tr[^>]+id="(\d+)"/gi;
let m;
while ((m = re.exec(html)) !== null) ids.push(m[1]);
const unique = [...new Set(ids)];
const pages = raw.pages_scraped;
const rowsApi = raw.rows_total;
return [{
  json: {
    success: raw.success !== false,
    pages_scraped: pages ?? null,
    rows_total_api: rowsApi ?? null,
    rows_counted_in_html: unique.length,
    verify_message: `pages_scraped=${pages ?? '?'} | rows_total=${rowsApi ?? '?'} | counted=${unique.length}`,
  },
}];

const sd = $getWorkflowStaticData('global');
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/London' });
if (sd.asbestosDailyDate !== today) {
  sd.asbestosDailyDate = today;
  sd.asbestosDailyLog = [];
}
const log = sd.asbestosDailyLog || [];
const seen = new Set(log.map((e) => `${e.works_id}::${e.corf}::${e.pdf}`));

for (const item of $('Expand Batch Results').all()) {
  const r = item.json || {};
  if (!r._newly_uploaded) continue;
  const pdf = String(r.asbestos_report_file || '').trim();
  const key = `${r.works_id}::${r.corf}::${pdf}`;
  if (seen.has(key)) continue;
  seen.add(key);
  log.push({
    at: new Date().toISOString(),
    corf: r.corf || '',
    works_id: r.works_id || '',
    address: r.address || '',
    uprn: r.uprn || '',
    pdf,
    sharepoint_match: pdf,
    status: 'Uploaded to EasyBOP',
  });
}
sd.asbestosDailyLog = log;
return $input.all();

function esc(t) {
  return String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}

const sd = $getWorkflowStaticData('global');
const today = new Date().toLocaleDateString('en-CA', { timeZone: 'Europe/London' });
const logs = (sd.asbestosDailyDate === today && Array.isArray(sd.asbestosDailyLog)) ? sd.asbestosDailyLog : [];
const reportDate = new Date().toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long', year: 'numeric', timeZone: 'Europe/London' });
const logo = 'https://jeffway.co.uk/wp-content/uploads/2025/05/jeffway-group-1.svg';

let jobRows = '';
if (logs.length) {
  jobRows = logs.map((l, i) => '<tr>'
    + '<td style="padding:8px;border-bottom:1px solid #eee;">' + esc(i + 1) + '</td>'
    + '<td style="padding:8px;border-bottom:1px solid #eee;">' + esc(l.corf || '-') + '</td>'
    + '<td style="padding:8px;border-bottom:1px solid #eee;">' + esc(l.works_id || '-') + '</td>'
    + '<td style="padding:8px;border-bottom:1px solid #eee;">' + esc(l.address || '-') + '</td>'
    + '<td style="padding:8px;border-bottom:1px solid #eee;">' + esc(l.pdf || '-') + '</td>'
    + '<td style="padding:8px;border-bottom:1px solid #eee;color:#15803d;font-weight:bold;">' + esc(l.status || 'Uploaded') + '</td>'
    + '</tr>').join('');
} else {
  jobRows = '<tr><td colspan="6" style="padding:16px;text-align:center;color:#666;">No asbestos reports uploaded to EasyBOP today.</td></tr>';
}

const html = [
  '<!DOCTYPE html><html><head><meta charset="UTF-8"></head>',
  '<body style="margin:0;padding:0;font-family:Arial,sans-serif;background:#f4f4f4;">',
  '<table width="100%" style="background:#f4f4f4;padding:20px;"><tr><td align="center">',
  '<table width="760" style="background:#fff;border-radius:8px;overflow:hidden;">',
  '<tr><td style="background:#000;padding:20px;text-align:center;"><img src="' + logo + '" style="max-width:160px;" alt="Jeffway"></td></tr>',
  '<tr><td style="padding:20px 24px 8px;"><h2 style="margin:0;color:#111;">Pre-Works Asbestos Upload — Daily Summary</h2>',
  '<p style="color:#777;font-size:13px;margin:8px 0 0;">' + esc(reportDate) + ' (Europe/London)</p></td></tr>',
  '<tr><td style="padding:8px 24px 24px;">',
  '<p style="font-size:13px;color:#444;margin:0 0 12px;">Reports matched from SharePoint <strong>Asbestos reports</strong> folder and uploaded to EasyBOP (Global Asbestos Survey).</p>',
  '<table width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;font-size:12px;">',
  '<tr style="background:#f3f3f3;">',
  '<th align="left" style="padding:8px;">#</th>',
  '<th align="left" style="padding:8px;">CORF</th>',
  '<th align="left" style="padding:8px;">Works ID</th>',
  '<th align="left" style="padding:8px;">Address</th>',
  '<th align="left" style="padding:8px;">SharePoint PDF</th>',
  '<th align="left" style="padding:8px;">Status</th>',
  '</tr>',
  jobRows,
  '</table></td></tr>',
  '<tr><td style="background:#f9f9f9;padding:16px;text-align:center;font-size:12px;color:#777;">Jeffway Group · Automated pre-works asbestos upload</td></tr>',
  '</table></td></tr></table></body></html>',
].join('');

return [{
  json: {
    _alert_subject: 'Jeffway — Pre-Works Asbestos uploads — ' + reportDate + ' (' + logs.length + ')',
    _alert_html: html,
    upload_count: logs.length,
  },
}];
